// A opens select choices; moving focus must never change or submit a filter.
let menuSelectDialog=null;
function closeMenuSelect(commitIndex=null){const state=menuSelectDialog;if(!state)return false;menuSelectDialog=null;state.popup.remove();for(const [node,inert]of state.inert)node.inert=inert;const el=state.select;if(!el.isConnected)return true;menuFocusElement(el);if(commitIndex!==null&&commitIndex!==el.selectedIndex){const option=el.options[commitIndex];if(option&&!option.disabled&&!option.hidden&&!option.parentElement?.disabled){el.selectedIndex=commitIndex;el.dispatchEvent(new Event('change',{bubbles:true}));}}return true;}
function openMenuSelect(el){if(menuSelectDialog||el.disabled)return;const popup=document.createElement('div');popup.className='menu-select-dialog';popup.setAttribute('role','dialog');popup.setAttribute('aria-modal','true');popup.setAttribute('aria-label',el.getAttribute('aria-label')||'条件を選択');const box=document.createElement('section'),title=document.createElement('h3');title.textContent=popup.getAttribute('aria-label');box.append(title);const hint=document.createElement('p');hint.textContent='十字キー：選択　A：確定　B：取消';box.append(hint);const list=document.createElement('div');list.className='menu-select-options';box.append(list);let selected=null;Array.from(el.options).forEach((option,index)=>{if(option.disabled||option.hidden||option.parentElement?.disabled)return;const button=document.createElement('button');button.type='button';button.textContent=option.textContent;button.setAttribute('aria-pressed',String(index===el.selectedIndex));button.onclick=()=>closeMenuSelect(index);button.onfocus=()=>button.scrollIntoView({block:'nearest'});list.append(button);if(index===el.selectedIndex)selected=button;});const cancel=document.createElement('button');cancel.type='button';cancel.textContent='取消';cancel.onclick=()=>closeMenuSelect();box.append(cancel);popup.append(box);const inert=Array.from($('card').children).map(node=>[node,node.inert]);for(const [node]of inert)node.inert=true;$('card').append(popup);menuSelectDialog={select:el,popup,inert};menuFocusElement(selected||list.querySelector('button')||cancel);}
const confirmSelectActivateBase=menuActivate;menuActivate=()=>{const el=document.activeElement;if(el?.tagName==='SELECT'&&$('card').contains(el)){openMenuSelect(el);return;}return confirmSelectActivateBase();};
const confirmSelectMoveBase=menuMove;menuMove=(dx,dy)=>{const el=document.activeElement;if(el?.tagName==='SELECT'&&$('card').contains(el)){const items=menuFocusables(),rects=items.map(n=>n.getBoundingClientRect()),index=items.indexOf(el);if(index>=0){const next=inventoryNextIndex(rects,index,dx,dy);if(items[next])menuFocusElement(items[next]);}return;}return confirmSelectMoveBase(dx,dy);};
const confirmSelectPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSelectDialog&&!menuSelectDialog.select.isConnected)closeMenuSelect();if(menuSelectDialog&&(padEdge(g,'back')||padEdge(g,'pause'))){closeMenuSelect();return;}return confirmSelectPadBase(g,l,r,dt);};
const confirmSelectCloseBase=closePanel;closePanel=(...args)=>{closeMenuSelect();return confirmSelectCloseBase(...args);};
addEventListener('keydown',e=>{if(menuSelectDialog&&e.key==='Escape'){closeMenuSelect();e.preventDefault();e.stopImmediatePropagation();}},true);
